const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const wuhan = ee.Geometry.Point([114.3055, 30.5928]);

  // February 2019 and February 2020
  const feb2019_start = '2019-02-01';
  const feb2019_end = '2019-02-28';
  const feb2020_start = '2020-02-01';
  const feb2020_end = '2020-02-29';

  // 2. Data Acquisition - Using MERRA-2 for PM2.5
  const getPM25Collection = function(startDate, endDate) {
    return ee.ImageCollection('NASA/GSFC/MERRA/aer/2')
      .filterDate(startDate, endDate)
      .select('PM25'); // PM2.5 dust column mass density (kg/m²)
  };

  const pm25_2019 = getPM25Collection(feb2019_start, feb2019_end);
  const pm25_2020 = getPM25Collection(feb2020_start, feb2020_end);

  // Check collection sizes
  const size2019 = pm25_2019.size().getInfo();
  const size2020 = pm25_2020.size().getInfo();

  console.log(`2019 Images: ${size2019}, 2020 Images: ${size2020}`);

  if (size2019 === 0 || size2020 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate monthly mean PM2.5
  const mean2019 = pm25_2019.mean();
  const mean2020 = pm25_2020.mean();

  // Get pixel counts and values
  const stats2019 = mean2019.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: wuhan,
    scale: 10000,
    maxPixels: 1e9
  }).getInfo();

  const stats2020 = mean2020.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: wuhan,
    scale: 10000,
    maxPixels: 1e9
  }).getInfo();

  const pm25_2019_val = stats2019.PM25_mean;
  const pm25_2020_val = stats2020.PM25_mean;
  const count2019 = stats2019.PM25_count;
  const count2020 = stats2020.PM25_count;

  console.log(`2019 PM2.5: ${pm25_2019_val?.toFixed(6)}, Pixels: ${count2019}`);
  console.log(`2020 PM2.5: ${pm25_2020_val?.toFixed(6)}, Pixels: ${count2020}`);

  // 4. Validation & Final Answer
  if (count2019 === 0 || count2020 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (pm25_2019_val === null || pm25_2020_val === null || 
      isNaN(pm25_2019_val) || isNaN(pm25_2020_val)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Check if values are reasonable (PM2.5 should be positive and typically < 1e-5 kg/m²)
  if (pm25_2019_val < 0 || pm25_2020_val < 0 || 
      pm25_2019_val > 1e-4 || pm25_2020_val > 1e-4) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare PM2.5 values
  if (pm25_2020_val > pm25_2019_val) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
